 "content": "def transform(grid):
    """Collapse four 4x4 color panels, resolving overlaps by 9 > 4 > 8 > 5."""
    starts = (0, 5, 10, 15)
    # Highest priority last, so it overwrites any lower-priority occupied cell.
    priority = (5, 8, 4, 9)
    out = [[0 for _ in range(4)] for _ in range(4)]
    for color, start in zip((8, 5, 9, 4), starts):
        for r in range(4):
            for c in range(4):
                if grid[r][start + c] != 0:
                    out[r][c] = color
    # Apply the priority order explicitly: panels 5, 8, 4, then 9.
    # (Loop above follows input layout; overwrite in priority order.)
    out = [[0 for _ in range(4)] for _ in range(4)]
    panel_start = {8: 0, 5: 5, 9: 10, 4: 15}
    for color in priority:
        start = panel_start[color]
        for r in range(4):
            for c in range(4):
                if grid[r][start + c] != 0:
                    out[r][c] = color
    return out
